#!/usr/bin/env python3
import sys
import json
import time
from urllib import request, error

API_URL = "http://127.0.0.1:4000/v1/chat/completions"
PROMPT = "Reply with exactly one word: OK"
TIMEOUT_SECONDS = 30


def load_models(config_path):
    with open(config_path, "r", encoding="utf-8") as f:
        data = json.load(f)

    if isinstance(data, list):
        items = data
    elif isinstance(data, dict):
        if isinstance(data.get("models"), list):
            items = data["models"]
        elif isinstance(data.get("data"), list):
            items = data["data"]
        else:
            raise ValueError(
                "JSON must be a list of models or an object with a 'models' (or 'data') list."
            )
    else:
        raise ValueError("Invalid JSON structure for model list.")

    models = []
    seen = set()

    for item in items:
        model_name = None

        if isinstance(item, str):
            model_name = item.strip()
        elif isinstance(item, dict):
            for key in ("id", "model", "name"):
                val = item.get(key)
                if isinstance(val, str) and val.strip():
                    model_name = val.strip()
                    break

        if model_name and model_name not in seen:
            seen.add(model_name)
            models.append(model_name)

    return models


def compact_text(text, limit=50):
    if text is None:
        return ""
    text = " ".join(str(text).split())
    return text[:limit]


def parse_error_message(raw):
    if not raw:
        return "Unknown error"
    try:
        obj = json.loads(raw)
        if isinstance(obj, dict):
            err = obj.get("error")
            if isinstance(err, dict):
                msg = err.get("message")
                if msg:
                    return str(msg)
            if "message" in obj:
                return str(obj["message"])
    except Exception:
        pass
    return str(raw)


def temperature_not_supported(error_text):
    msg = parse_error_message(error_text).lower()
    return (
        "temperature" in msg
        and (
            "not supported" in msg
            or "unsupported" in msg
            or "unknown" in msg
            or "invalid" in msg
            or "not allowed" in msg
        )
    )


def send_chat(payload):
    body = json.dumps(payload).encode("utf-8")
    req = request.Request(
        API_URL,
        data=body,
        method="POST",
        headers={"Content-Type": "application/json"},
    )

    start = time.time()
    try:
        with request.urlopen(req, timeout=TIMEOUT_SECONDS) as resp:
            raw = resp.read().decode("utf-8", errors="replace")
            elapsed = time.time() - start
            data = json.loads(raw)
            return True, elapsed, data, None
    except error.HTTPError as e:
        raw = e.read().decode("utf-8", errors="replace")
        elapsed = time.time() - start
        return False, elapsed, None, raw
    except Exception as e:
        elapsed = time.time() - start
        return False, elapsed, None, str(e)


def extract_response_text(resp_json):
    try:
        return str(resp_json["choices"][0]["message"]["content"]).strip()
    except Exception:
        return ""


def test_model(model_name):
    model_start = time.time()

    payload = {
        "model": model_name,
        "messages": [{"role": "user", "content": PROMPT}],
        "max_tokens": 20,
        "temperature": 0,
    }

    ok, _, data, err = send_chat(payload)

    # Retry once without temperature if unsupported
    if not ok and temperature_not_supported(err):
        payload.pop("temperature", None)
        ok, _, data, err = send_chat(payload)

    latency = time.time() - model_start

    if ok:
        text = extract_response_text(data)
        passed = text == "OK"
        status = "PASS" if passed else "FAIL"
        preview = compact_text(text, 50) or "<empty>"
    else:
        status = "FAIL"
        preview = compact_text(parse_error_message(err), 50)

    return {
        "model": model_name,
        "status": status,
        "latency": latency,
        "response": preview,
    }


def print_table(results):
    if not results:
        print("No results.")
        return

    headers = ("Model", "Status", "Latency", "Response")
    latency_strings = [f"{r['latency']:.2f}s" for r in results]

    w_model = max(len(headers[0]), max(len(r["model"]) for r in results))
    w_status = max(len(headers[1]), max(len(r["status"]) for r in results))
    w_latency = max(len(headers[2]), max(len(s) for s in latency_strings))
    w_response = max(len(headers[3]), max(len(r["response"]) for r in results))

    line = (
        f"{headers[0]:<{w_model}}  "
        f"{headers[1]:<{w_status}}  "
        f"{headers[2]:<{w_latency}}  "
        f"{headers[3]:<{w_response}}"
    )
    sep = "-" * len(line)

    print(line)
    print(sep)

    for r, lat in zip(results, latency_strings):
        print(
            f"{r['model']:<{w_model}}  "
            f"{r['status']:<{w_status}}  "
            f"{lat:<{w_latency}}  "
            f"{r['response']:<{w_response}}"
        )


def main():
    if len(sys.argv) != 2:
        print(f"Usage: {sys.argv[0]} <models_config.json>")
        sys.exit(1)

    config_path = sys.argv[1]

    try:
        models = load_models(config_path)
    except Exception as e:
        print(f"Failed to load models from {config_path}: {e}")
        sys.exit(1)

    if not models:
        print("No models found in config.")
        sys.exit(1)

    results = []
    for model in models:
        results.append(test_model(model))

    print_table(results)

    total = len(results)
    working = sum(1 for r in results if r["status"] == "PASS")
    failed = total - working
    print(f"\nTotal: {total} models | ✅ {working} working | ❌ {failed} failed")


if __name__ == "__main__":
    main()
